CREATE TABLE `compliance_organisations` ( `id` text PRIMARY KEY NOT NULL, `organisation_code` text NOT NULL, `legal_name` text NOT NULL, `trading_name` text DEFAULT '' NOT NULL, `abn` text DEFAULT '' NOT NULL, `status` text DEFAULT 'active' NOT NULL CHECK (`status` IN ('active', 'suspended', 'retired')), `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_organisations_code_idx` ON `compliance_organisations` (`organisation_code`);
CREATE INDEX `compliance_organisations_status_name_idx` ON `compliance_organisations` (`status`, `trading_name`, `legal_name`);
CREATE TABLE `compliance_users` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `firebase_uid` text NOT NULL, `email` text NOT NULL, `display_name` text DEFAULT '' NOT NULL, `role` text NOT NULL CHECK (`role` IN ('admin', 'case_manager', 'reviewer', 'auditor')), `status` text DEFAULT 'active' NOT NULL CHECK (`status` IN ('active', 'suspended', 'revoked')), `created_by_uid` text NOT NULL, `last_login_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_users_org_uid_idx` ON `compliance_users` (`organisation_id`, `firebase_uid`);
CREATE UNIQUE INDEX `compliance_users_org_email_idx` ON `compliance_users` (`organisation_id`, `email` COLLATE NOCASE);
CREATE INDEX `compliance_users_uid_status_idx` ON `compliance_users` (`firebase_uid`, `status`);
CREATE INDEX `compliance_users_org_role_status_idx` ON `compliance_users` (`organisation_id`, `role`, `status`);
CREATE TABLE `compliance_programs` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `program_code` text NOT NULL, `name` text NOT NULL, `scheme_kind` text NOT NULL, `jurisdiction` text NOT NULL CHECK ( `jurisdiction` IN ('AU', 'ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA') ), `administering_body` text NOT NULL, `official_source_url` text NOT NULL, `official_source_title` text NOT NULL, `official_source_version` text DEFAULT '' NOT NULL, `official_source_sha256` text DEFAULT '' NOT NULL CHECK (`official_source_sha256` = '' OR ( length(`official_source_sha256`) = 64 AND `official_source_sha256` NOT GLOB '*[^0-9a-fA-F]*' )), `official_source_checked_at` text NOT NULL, `publish_state` text DEFAULT 'draft' NOT NULL CHECK (`publish_state` IN ('draft', 'published', 'withdrawn')) CHECK (`publish_state` = 'draft' OR length(`official_source_sha256`) = 64), `published_by_uid` text DEFAULT '' NOT NULL, `published_at` text DEFAULT '' NOT NULL, `withdrawn_by_uid` text DEFAULT '' NOT NULL, `withdrawn_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`publish_state` = 'draft' AND `published_by_uid` = '' AND `published_at` = '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'published' AND trim(`published_by_uid`) <> '' AND trim(`published_at`) <> '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'withdrawn' AND trim(`published_by_uid`) <> '' AND trim(`published_at`) <> '' AND trim(`withdrawn_by_uid`) <> '' AND trim(`withdrawn_at`) <> '') ) );
CREATE UNIQUE INDEX `compliance_programs_org_code_idx` ON `compliance_programs` (`organisation_id`, `program_code`);
CREATE INDEX `compliance_programs_org_state_idx` ON `compliance_programs` (`organisation_id`, `publish_state`, `name`);
CREATE INDEX `compliance_programs_scheme_jurisdiction_idx` ON `compliance_programs` (`scheme_kind`, `jurisdiction`, `publish_state`);
CREATE TABLE `compliance_activity_versions` ( `id` text PRIMARY KEY NOT NULL, `program_id` text NOT NULL, `activity_key` text NOT NULL, `version` integer NOT NULL CHECK (`version` > 0), `title` text NOT NULL, `service_category` text NOT NULL CHECK (`service_category` IN ( 'assessment', 'solar', 'battery', 'heating-cooling', 'hot-water', 'draught-proofing', 'insulation', 'glazing', 'window-coverings', 'ev-charging', 'electrical', 'plumbing', 'mounting-hardware', 'controls', 'other' )), `registry_activity_code` text DEFAULT '' NOT NULL, `specification_part` text DEFAULT '' NOT NULL, `product_category` text NOT NULL, `scenario_code` text DEFAULT '' NOT NULL, `scenario` text NOT NULL, `jurisdiction` text NOT NULL CHECK ( `jurisdiction` IN ('AU', 'ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA') ), `effective_from` text NOT NULL CHECK (date(`effective_from`) = `effective_from`), `effective_to` text DEFAULT '' NOT NULL CHECK ( `effective_to` = '' OR ( date(`effective_to`) = `effective_to` AND `effective_to` >= `effective_from` ) ), `official_source_url` text NOT NULL, `official_source_title` text NOT NULL, `official_source_version` text DEFAULT '' NOT NULL, `official_source_sha256` text DEFAULT '' NOT NULL CHECK (`official_source_sha256` = '' OR ( length(`official_source_sha256`) = 64 AND `official_source_sha256` NOT GLOB '*[^0-9a-fA-F]*' )), `official_source_checked_at` text NOT NULL, `requirements_snapshot` text DEFAULT '{}' NOT NULL CHECK (json_valid(`requirements_snapshot`)), `publish_state` text DEFAULT 'draft' NOT NULL CHECK (`publish_state` IN ('draft', 'published', 'withdrawn')) CHECK (`publish_state` = 'draft' OR length(`official_source_sha256`) = 64), `calculation_approval_state` text DEFAULT 'not_assessed' NOT NULL CHECK (`calculation_approval_state` IN ( 'not_assessed', 'approved', 'rejected', 'not_applicable' )), `published_by_uid` text DEFAULT '' NOT NULL, `published_at` text DEFAULT '' NOT NULL, `withdrawn_by_uid` text DEFAULT '' NOT NULL, `withdrawn_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`publish_state` = 'draft' AND `published_by_uid` = '' AND `published_at` = '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'published' AND trim(`published_by_uid`) <> '' AND trim(`published_at`) <> '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'withdrawn' AND trim(`published_by_uid`) <> '' AND trim(`published_at`) <> '' AND trim(`withdrawn_by_uid`) <> '' AND trim(`withdrawn_at`) <> '') ) );
CREATE UNIQUE INDEX `compliance_activity_versions_key_version_idx` ON `compliance_activity_versions` (`program_id`, `activity_key`, `version`);
CREATE INDEX `compliance_activity_versions_program_state_idx` ON `compliance_activity_versions` (`program_id`, `publish_state`, `effective_from`, `effective_to`);
CREATE INDEX `compliance_activity_versions_installer_idx` ON `compliance_activity_versions` (`service_category`, `jurisdiction`, `publish_state`, `effective_from`);
CREATE INDEX `compliance_activity_versions_registry_idx` ON `compliance_activity_versions` (`registry_activity_code`, `specification_part`, `scenario_code`);
CREATE TABLE `compliance_cases` ( `id` text PRIMARY KEY NOT NULL, `case_number` text NOT NULL, `organisation_id` text NOT NULL, `program_id` text NOT NULL, `work_order_id` text NOT NULL, `installer_uid` text NOT NULL, `activity_version_id` text NOT NULL, `activity_date` text NOT NULL CHECK ( length(`activity_date`) = 10 AND `activity_date` GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(`activity_date`) = `activity_date` ), `site_jurisdiction` text NOT NULL CHECK ( `site_jurisdiction` IN ('ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA') ), `activity_snapshot` text NOT NULL CHECK (json_valid(`activity_snapshot`)), `status` text DEFAULT 'draft' NOT NULL CHECK (`status` IN ( 'draft', 'ready_for_submission', 'submitted', 'in_review', 'changes_requested', 'accepted', 'rejected', 'closed' )), `evidence_status` text DEFAULT 'not_started' NOT NULL CHECK (`evidence_status` IN ( 'not_started', 'in_progress', 'complete', 'changes_required', 'verified' )), `revision` integer DEFAULT 1 NOT NULL CHECK (`revision` > 0), `created_by_type` text NOT NULL CHECK (`created_by_type` IN ('installer', 'compliance', 'platform')), `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_cases_number_idx` ON `compliance_cases` (`case_number`);
CREATE INDEX `compliance_cases_org_status_idx` ON `compliance_cases` (`organisation_id`, `status`, `evidence_status`, `updated_at`);
CREATE INDEX `compliance_cases_work_order_idx` ON `compliance_cases` (`work_order_id`, `created_at`);
CREATE INDEX `compliance_cases_installer_idx` ON `compliance_cases` (`installer_uid`, `status`, `updated_at`);
CREATE INDEX `compliance_cases_activity_idx` ON `compliance_cases` (`activity_version_id`, `created_at`);
CREATE TABLE `compliance_case_events` ( `id` text PRIMARY KEY NOT NULL, `case_id` text NOT NULL, `organisation_id` text NOT NULL, `event_type` text NOT NULL, `actor_type` text NOT NULL CHECK (`actor_type` IN ('installer', 'compliance', 'platform')), `actor_uid` text NOT NULL, `summary` text NOT NULL, `metadata` text DEFAULT '{}' NOT NULL CHECK (json_valid(`metadata`)), `created_at` text NOT NULL );
CREATE INDEX `compliance_case_events_case_time_idx` ON `compliance_case_events` (`case_id`, `created_at`);
CREATE INDEX `compliance_case_events_org_time_idx` ON `compliance_case_events` (`organisation_id`, `created_at`);
